"""Record/check the explicit Clojure char adaptation and pinned helper inputs."""
from pathlib import Path
import hashlib,json,sys
ROOT=Path(__file__).resolve().parents[2];BASE=Path(__file__).resolve().parent
record_path=ROOT/'docs/compatibility/bootstrap/clojure-char.json'
paths=['crates/suss-cli/tests/clojure_char.rs','crates/suss-compile/src/portable/hir.rs','crates/suss-compile/src/portable/hir/local_hints.rs','crates/suss-compile/src/portable/emit/unboxed.rs','crates/suss-compile/src/portable/emit/unboxed/numeric_casts.rs','crates/suss-compile/src/runtime_abi/bitwise.rs','crates/suss-compile/src/runtime_abi/numeric.rs','docs/compatibility/bootstrap/exact-integers.sus','runtime/numeric/src/lib.rs','runtime/numeric/artifact/manifest.json','runtime/numeric/artifact/numeric.wasm','docs/compatibility/character/NOTICE','results/m12-character-coercion/upstream-char.clj','results/m12-character-coercion/primary/cases.json','results/m12-character-coercion/float-primary/cases.json','results/m12-character-coercion/object-float-probe/cases.json','results/m12-character-coercion/exact-number-primary/cases.json','results/m12-character-coercion/effects/cases.json']
primary=json.loads((BASE/'source-provenance.json').read_text())
record={'upstream':primary,'license':'EPL-1.0 for retained/adapted Clojure form; original Suss native implementation and existing separately licensed ryu-js helper','adaptation':'Object, primitive Double and primitive Float source classes select distinct checked UTF-16 unit casts before backend storage inference. Object conversion uses exact Number.longValue low bits; primitive floating conversion checks the original value. Source-float diagnostics use binary32 shortest digits. Native helpers are allocator-free; Java is a development oracle only.','platform_differences':['One-unit UTF-16 Strings are also characters under the accepted design; three original String controls differ from JVM Character coercion.','ADR-0003 returns a Double from float. A first-class rounded input retains its widened Double value in range text, rather than inventing a boxed Float; one fresh control records this difference.'],'files':{p:hashlib.sha256((ROOT/p).read_bytes()).hexdigest() for p in paths}}
if '--record' in sys.argv:record_path.write_text(json.dumps(record,indent=2)+'\n')
else:assert json.loads(record_path.read_text())==record,'character provenance is stale; inspect changes before explicitly recording'
print('Clojure char source/provenance '+('recorded' if '--record' in sys.argv else 'verified'))
